Repair the complete CommonJS source below and return a corrected complete source file. Export exactly `{ sharedLabels }`.

`sharedLabels(left, right)` accepts two arrays containing only strings. Return the distinct strings present in both arrays, sorted by JavaScript's default string ordering. Duplicate occurrences must appear once. Empty arrays return an empty array. Inputs must not be sorted, mutated, or retained. Throw `TypeError` if either argument is not an array or contains a non-string element.

```javascript
'use strict';

function sharedLabels(left, right) {
  if (!Array.isArray(left) || !Array.isArray(right)) {
    throw new TypeError('both inputs must be arrays');
  }
  if (left.some((value) => typeof value !== 'string') ||
      right.some((value) => typeof value !== 'string')) {
    throw new TypeError('all labels must be strings');
  }

  const rightLabels = new Set(right);
  const result = new Set();
  for (const label of left) {
    if (!rightLabels.has(label)) result.add(label);
  }
  return Array.from(result).sort();
}

module.exports = { sharedLabels };
```

