'use strict';

const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api).sort(), ['sharedLabels']);
const { sharedLabels } = api;
assert.strictEqual(typeof sharedLabels, 'function');

assert.deepStrictEqual(sharedLabels([], []), []);
assert.deepStrictEqual(sharedLabels([], ['a']), []);
assert.deepStrictEqual(sharedLabels(['a'], []), []);
assert.deepStrictEqual(
  sharedLabels(['pear', 'apple', 'pear', 'banana'], ['banana', 'pear', 'pear', 'orange']),
  ['banana', 'pear']
);
assert.deepStrictEqual(
  sharedLabels(['z', 'A', '10', '2', 'a', ''], ['a', '2', '', 'A', 'z', '10']),
  ['', '10', '2', 'A', 'a', 'z']
);
assert.deepStrictEqual(sharedLabels(['same', 'same'], ['same', 'same']), ['same']);
assert.deepStrictEqual(sharedLabels(['Case'], ['case']), []);

const left = ['c', 'a', 'b', 'a'];
const right = ['b', 'd', 'a', 'b'];
const leftSnapshot = left.slice();
const rightSnapshot = right.slice();
const result = sharedLabels(left, right);
assert.deepStrictEqual(result, ['a', 'b']);
assert.deepStrictEqual(left, leftSnapshot);
assert.deepStrictEqual(right, rightSnapshot);
left[0] = 'changed';
right[0] = 'changed';
assert.deepStrictEqual(result, ['a', 'b']);
result.push('new');
assert.deepStrictEqual(sharedLabels(['b', 'a'], ['a', 'b']), ['a', 'b']);

for (const pair of [
  [undefined, []],
  [[], undefined],
  [null, []],
  [[], null],
  [{}, []],
  [[], 'labels'],
  [new Set(['a']), []]
]) {
  assert.throws(() => sharedLabels(pair[0], pair[1]), TypeError);
}
for (const invalid of [undefined, null, 1, true, {}, [], new String('a')]) {
  assert.throws(() => sharedLabels(['a', invalid], ['a']), TypeError);
  assert.throws(() => sharedLabels(['a'], ['a', invalid]), TypeError);
}

